function VerticalPanelSlider({ label, language, slides }: { label: string; language: Language; slides: ReactNode[] }) {
  const [index, setIndex] = useState(0);
  const [direction, setDirection] = useState<"up" | "down">("down");
  const controlText = language === "fr"
    ? { previous: "Panneau précédent", next: "Panneau suivant", controls: "Commandes du carrousel" }
    : language === "ar"
      ? { previous: "اللوحة السابقة", next: "اللوحة التالية", controls: "أزرار التنقل بين اللوحات" }
      : { previous: "Previous panel", next: "Next panel", controls: "Carousel controls" };
  const format = (value: number) => new Intl.NumberFormat(language === "fr" ? "fr-FR" : language === "ar" ? "ar-MA" : "en-GB", { minimumIntegerDigits: 2, useGrouping: false }).format(value);
  const move = (step: -1 | 1) => {
    setDirection(step < 0 ? "up" : "down");
    setIndex((current) => Math.max(0, Math.min(slides.length - 1, current + step)));
  };

  if (!slides.length) return null;
  return <div className="vertical-slider" aria-label={label}>
    <div className={`vertical-slider-panel slide-${direction}`} key={index} aria-live="polite">{slides[index]}</div>
    {slides.length > 1 && <nav className="vertical-slider-controls" aria-label={controlText.controls}>
      <button type="button" aria-label={controlText.previous} title={controlText.previous} disabled={index === 0} onClick={() => move(-1)}>↑</button>
      <span className="vertical-slider-count" aria-hidden="true">{format(index + 1)} / {format(slides.length)}</span>
      <button type="button" aria-label={controlText.next} title={controlText.next} disabled={index === slides.length - 1} onClick={() => move(1)}>↓</button>
    </nav>}
  </div>;
}

